-- Create "organization_branding_settings" table
CREATE TABLE "organization_branding_settings" ("id" character varying NOT NULL, "created_at" timestamptz NULL, "updated_at" timestamptz NULL, "created_by" character varying NULL, "updated_by" character varying NULL, "updated_by_impersonator" character varying NULL, "deleted_at" timestamptz NULL, "deleted_by" character varying NULL, "tags" jsonb NULL, "remove_assessment_branding" boolean NULL DEFAULT false, "primary_color" character varying NULL, "secondary_color" character varying NULL, "background_color" character varying NULL, "text_color" character varying NULL, "font_family" character varying NULL, "organization_id" character varying NULL, PRIMARY KEY ("id"), CONSTRAINT "organization_branding_settings_organizations_branding_setting" FOREIGN KEY ("organization_id") REFERENCES "organizations" ("id") ON UPDATE NO ACTION ON DELETE SET NULL);
-- Create index "organization_branding_settings_organization_id_key" to table: "organization_branding_settings"
CREATE UNIQUE INDEX "organization_branding_settings_organization_id_key" ON "organization_branding_settings" ("organization_id");
-- Create index "organizationbrandingsetting_organization_id" to table: "organization_branding_settings"
CREATE UNIQUE INDEX "organizationbrandingsetting_organization_id" ON "organization_branding_settings" ("organization_id") WHERE (deleted_at IS NULL);
